<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><h1 class="h3 mb-4">Dashboard</h1><div class="row g-3 mb-4"><?php foreach([["Today's Orders",$todayOrders],['Pending Orders',$pendingOrders],["Today's Paid Sales",format_bdt($todaySales)],['Delivered Orders',$deliveredOrders],['Customers',$customerCount],['Admin Users',$adminCount]] as [$label,$value]): ?><div class="col-sm-6 col-xl-3"><div class="card stat p-3 h-100"><div class="text-muted"><?= esc($label) ?></div><div class="fs-2 fw-semibold"><?= esc($value) ?></div></div></div><?php endforeach ?></div><div class="row g-4"><div class="col-xl-8"><div class="card border-0"><div class="card-header bg-white fw-semibold">Recent Orders</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Time</th></tr></thead><tbody><?php foreach($recentOrders as $o): ?><tr><td><a href="<?= url_to('admin.orders.show',$o['id']) ?>"><?= esc($o['order_no']) ?></a></td><td><?= esc($o['customer_name']) ?></td><td><?= format_bdt($o['grand_total']) ?></td><td><?= esc($o['order_status']) ?></td><td><?= esc($o['placed_at']) ?></td></tr><?php endforeach ?><?php if(!$recentOrders): ?><tr><td colspan="5" class="text-center">No orders yet.</td></tr><?php endif ?></tbody></table></div></div></div><div class="col-xl-4"><div class="card border-0"><div class="card-header bg-white fw-semibold">Recent Admin Activity</div><div class="p-3"><?php foreach($activities as $a): ?><p class="small"><strong><?= esc($a['admin_name']??'System') ?></strong> · <?= esc($a['action']) ?><br><?= esc($a['created_at']) ?></p><?php endforeach ?></div></div></div></div><?= $this->endSection() ?>
